      { only = "Rogue", source = "polestar:forever/class/rogue/the-eye-of-bhossca",
        { "text", text = "The Scarlet Monastery" },
        { "text", text = "The monastery stands in the far north-east of Tirisfal Glades. Go in alone, out of any group. Before entering, take the Scarlet Initiate's Uniform from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), Pick Pocket a |cOXP_FRIENDLY_Scarlet Scryer|r or Scarlet Crier for the |cOXP_LOOT_Scryer's Key|r. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the |cOXP_LOOT_Reliquary Key|r from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance." },
        { "reach", text = "Scarlet Monastery", x = 82.6, y = 33.8, zone = "1420" },
        { "text", text = "Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings." },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/the-eye-of-bhossca",
        { "text", text = "Back to the dead drop" },
        { "text", text = "Place the eye in the |cOXP_PICK_Dead Drop|r near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared." },
        { "goto", x = 47.12, y = 70.99, zone = "1421" },
        { "turnin", quest = 78676, text = "Turn in The Eye of Bhossca" },
        { "goto", x = 47.12, y = 70.99, zone = "1421" },
        { "accept", quest = 78699, text = "Accept The Eye of Bhossca" },
        { "goto", x = 47.12, y = 70.99, zone = "1421" },
        { "turnin", quest = 78699, text = "Turn in The Eye of Bhossca (|cOXP_LOOT_Ruby-Adorned Blade|r)" },
      },
      { only = "Orc Shaman/Troll Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "Class quest: {quest:1531} and the Tempest's Weapons (Horde)" },
        { "text", text = "|cOXP_FRIENDLY_Searn Firewarder|r" },
        { "text", text = "At 30 |cOXP_FRIENDLY_Searn Firewarder|r in the |cOXP_PICK_Valley of Wisdom|r sends you to |cOXP_FRIENDLY_Prate Cloudseer|r in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the |cOXP_LOOT_Air Totem|r she gives." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 37.96, y = 37.73, zone = "1454" },
        { "accept", quest = 1531, text = "Accept Call of Air" },
        { "target", name = "Searn Firewarder" },
      },
      { only = "Skyborne Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "|cOXP_FRIENDLY_Alaana Stormwalker|r" },
        { "text", text = "At 30 Skyborne shamans get their own Call of Air. |cOXP_FRIENDLY_Alaana Stormwalker|r waits where the airship from Zephras Isle lands, in northern Mulgore beside Thunder Bluff. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to |cOXP_FRIENDLY_Xanis Flameweaver|r in Thunder Bluff (next step): the trainers' Call of Air is open to Skyborne and gives the same totem." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 33.38, y = 22.57, zone = "1412" },
        { "accept", optional = true, quest = 96136, text = "Accept Call of Air" },
        { "target", name = "Alaana Stormwalker" },
      },
      { only = "Tauren Shaman/Skyborne Shaman", source = "polestar:forever/class/shaman/call-of-air-horde", when = { { "onquest", neg = true, quests = { 96136 } }, { "onquest", neg = true, quests = { 1531 } } },
        { "text", text = "|cOXP_FRIENDLY_Xanis Flameweaver|r" },
        { "text", text = "At 30 |cOXP_FRIENDLY_Xanis Flameweaver|r, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to |cOXP_FRIENDLY_Prate Cloudseer|r in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem Prate gives. Already carry |cOXP_FRIENDLY_Searn Firewarder|r's Call of Air from Orgrimmar? It goes to |cOXP_FRIENDLY_Prate Cloudseer|r too: skip |cOXP_FRIENDLY_Xanis Flameweaver|r." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 25.16, y = 20.51, zone = "1456" },
        { "accept", quest = 1532, text = "Accept Call of Air" },
        { "target", name = "Xanis Flameweaver" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "|cOXP_FRIENDLY_Prate Cloudseer|r" },
        { "text", text = "Fly to Freewind Post. |cOXP_FRIENDLY_Prate Cloudseer|r stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running." },
        { "reach", text = "|cOXP_FRIENDLY_Prate Cloudseer|r", x = 53.5, y = 42.6, zone = "1441" },
      },
