        { "goto", x = 53.54, y = 42.65, zone = "1441" },
        { "turnin", quest = 1531, text = "Turn in Call of Air (|cOXP_FRIENDLY_Prate Cloudseer|r: your |cOXP_LOOT_Air Totem|r)" },
        { "target", name = "Prate Cloudseer" },
      },
