      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "Twisted Air Totems" },
        { "text", text = "Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of Shadowprey Village in western Desolace carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw Jumping Lightning: pull one at a time. Respawn about five minutes." },
        { "xp", level = 36, text = "Reach level 36" },
        { "goto", x = 32.59, y = 59.75, zone = "1443" },
        { "complete", obj = 4, quest = 79361, text = "Twisted Air Totem: 5" },
        { "mob", name = "Maraudine Scout" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "Twisted Water Totems" },
        { "text", text = "Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of Brackenwall Village in northern Dustwallow Marsh carry them." },
        { "xp", level = 34, text = "Reach level 34" },
        { "goto", x = 57.15, y = 21.37, zone = "1445" },
        { "complete", obj = 1, quest = 79361, text = "Twisted Water Totem: 5" },
        { "mob", name = "Mirefin Puddlejumper" },
        { "mob", name = "Mirefin Murloc" },
        { "mob", name = "Mirefin Warrior" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "Twisted Fire Totems" },
        { "text", text = "Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of Angor Fortress in the Badlands carry them; the Shamans drop Fire Nova Totems and a |cOXP_FRIENDLY_Healing Ward|r, the Bonesnappers run for help when hurt. Respawn about five minutes." },
        { "xp", level = 36, text = "Reach level 36" },
        { "goto", x = 50.46, y = 68.43, zone = "1418" },
        { "complete", obj = 3, quest = 79361, text = "Twisted Fire Totem: 5" },
        { "mob", name = "Stonevault Bonesnapper" },
        { "mob", name = "Stonevault Shaman" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "Twisted Earth Totems" },
        { "text", text = "Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of Stonard in the Swamp of Sorrows carry them; most run for help when hurt." },
        { "xp", level = 33, text = "Reach level 33" },
        { "goto", x = 48.46, y = 31.13, zone = "1435" },
        { "complete", obj = 2, quest = 79361, text = "Twisted Earth Totem: 5" },
        { "mob", name = "Lost One Mudlurker" },
        { "mob", name = "Lost One Fisherman" },
        { "mob", name = "Lost One Hunter" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "|cOXP_FRIENDLY_Prate Cloudseer|r" },
        { "goto", x = 53.54, y = 42.65, zone = "1441" },
