        { "accept", quest = 79366, text = "Accept Heed My Call" },
        { "target", name = "Prate Cloudseer" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "The steam pools" },
        { "text", text = "|cOXP_FRIENDLY_Prate Cloudseer|r hands you the |cOXP_LOOT_Corrupted Totems|r. Place the |cOXP_LOOT_Corrupted Totems|r at the steam pools north-west of Freewind Post to call the corrupted elementals and then the |cOXP_ENEMY_Ravaging Tempest|r; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The |cOXP_LOOT_Eye of the Tempest|r drops about every other kill, and every group member can loot it." },
        { "xp", level = 38, text = "Reach level 38" },
        { "goto", x = 37.22, y = 41.58, zone = "1441" },
        { "collect", count = 1, item = 212792, text = "Eye of the Tempest: 1 (|cOXP_LOOT_Eye of the Tempest|r, from the |cOXP_ENEMY_Ravaging Tempest|r)" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "|cOXP_FRIENDLY_Rau Cliffrunner|r" },
        { "goto", x = 46.14, y = 51.71, zone = "1441" },
        { "turnin", quest = 79366, text = "Turn in Heed My Call" },
        { "target", name = "Rau Cliffrunner" },
        { "goto", x = 46.14, y = 51.71, zone = "1441" },
        { "accept", quest = 79442, text = "Accept The Tempest's Weapons" },
        { "target", name = "Rau Cliffrunner" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-horde",
        { "text", text = "|cOXP_FRIENDLY_Bath'rah the Windwatcher|r" },
        { "text", text = "|cOXP_FRIENDLY_Bath'rah the Windwatcher|r camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: |cOXP_LOOT_Lightning's Grasp|r, |cOXP_LOOT_Tidebringer's Claw|r or |cOXP_LOOT_Rage of the Storm|r; the |cOXP_LOOT_Elementalist's Guard|r shield comes with it." },
        { "goto", x = 80.5, y = 66.92, zone = "1416" },
        { "turnin", quest = 79442, text = "Turn in The Tempest's Weapons (|cOXP_FRIENDLY_Bath'rah the Windwatcher|r: the |cOXP_LOOT_Elementalist's Guard|r and your weapon)" },
        { "target", name = "Bath'rah the Windwatcher" },
      },
      { only = "Human Warrior/NightElf Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/whirlwind-weapon",
        { "text", text = "Class quest: {quest:1792}" },
        { "text", text = "The Islander (Stormwind)" },
        { "text", text = "At 30, |cOXP_FRIENDLY_Wu Shen|r, beside |cOXP_FRIENDLY_Ilsa Corbin|r in the warrior trainers' building of |cOXP_PICK_Old Town|r, sends you to |cOXP_FRIENDLY_Klannoc Macleod|r on Fray Island in the Barrens." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 80.55, y = 59.87, zone = "1453" },
        { "accept", quest = 1718, text = "Accept The Islander" },
        { "target", name = "Wu Shen" },
      },
      { only = "Dwarf Warrior/Gnome Warrior", source = "polestar:forever/class/warrior/whirlwind-weapon",
        { "text", text = "The Islander (Ironforge)" },
        { "text", text = "At 30, |cOXP_FRIENDLY_Kelv Sternhammer|r, the warrior trainer of Ironforge, sends you to |cOXP_FRIENDLY_Klannoc Macleod|r on Fray Island in the Barrens." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 70.34, y = 90.65, zone = "1455" },
