        { "text", text = "The Islander (Orgrimmar)" },
        { "text", text = "At 30, |cOXP_FRIENDLY_Sorek|r in the |cOXP_PICK_Valley of Honor|r sends you to |cOXP_FRIENDLY_Klannoc Macleod|r on Fray Island in the Barrens." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 80.39, y = 32.38, zone = "1454" },
        { "accept", quest = 1718, text = "Accept The Islander" },
        { "target", name = "Sorek" },
      },
      { only = "Tauren Warrior", source = "polestar:forever/class/warrior/whirlwind-weapon",
        { "text", text = "The Islander (Thunder Bluff)" },
        { "text", text = "At 30, |cOXP_FRIENDLY_Torm Ragetotem|r, the warrior trainer of Thunder Bluff, sends you to |cOXP_FRIENDLY_Klannoc Macleod|r on Fray Island in the Barrens." },
        { "xp", level = 30, text = "Reach level 30" },
