        { "collect", count = 8, item = 4481, text = "Cresting Charm: 8 (|cOXP_LOOT_Cresting Charm|r, from Cresting Exiles)" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/whirlwind-weapon",
        { "text", text = "Essence of the Exile" },
        { "text", text = "Click |cOXP_PICK_Bath'rah's Cauldron|r with the 24 charms in your bags and Cyclonian in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the Essence of the Exile." },
        { "goto", x = 79.32, y = 66.8, zone = "1416" },
        { "turnin", quest = 1714, text = "Turn in Essence of the Exile (|cOXP_PICK_Bath'rah's Cauldron|r: Essence of the Exile)" },
        { "goto", x = 80.5, y = 66.9, zone = "1416" },
        { "complete", obj = 3, quest = 1712, text = "Essence of the Exile: 1 (Essence of the Exile, from the cauldron by |cOXP_FRIENDLY_Bath'rah the Windwatcher|r)" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/whirlwind-weapon",
        { "text", text = "The Summoning" },
        { "text", text = "Back to |cOXP_FRIENDLY_Bath'rah the Windwatcher|r. Accepting The Summoning starts his ritual, and Cyclonian appears just north of his camp. Cyclonian is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a |cOXP_LOOT_Nature Protection Potion|r soaks it), whirls, and Knock Away throws you far while it heals itself as you run back: fight with your back to a slope or rock. The |cOXP_LOOT_Whirlwind Heart|r always drops. If the fight fails |cOXP_FRIENDLY_Bath'rah the Windwatcher|r stops answering: abandon The Summoning and take it again for a new summon; the earlier items are not needed again." },
        { "goto", x = 80.5, y = 66.92, zone = "1416" },
        { "turnin", quest = 1712, text = "Turn in Cyclonian" },
        { "target", name = "Bath'rah the Windwatcher" },
