      { only = "Mage", source = "polestar:forever/class/mage/celestial-orb",
        { "text", text = "|cOXP_FRIENDLY_Tabetha|r" },
        { "text", text = "|cOXP_FRIENDLY_Tabetha|r's cottage is deep in the marsh west of Theramore, just north of the Stonemaul Ruins; come in from the west road, the elites roam its east side." },
        { "goto", x = 46.06, y = 57.09, zone = "1445" },
        { "turnin", quest = 1953, text = "Turn in Return to the Marsh" },
