      { only = "Mage", source = "polestar:forever/class/mage/celestial-orb",
        { "text", text = "Power in Uldaman" },
        { "text", text = "Uldaman is a dungeon in the northern Badlands: a group of five, from level 40 here. Go in by the rear entrance, a cave in Dustwind Gulch south-east of the main entrance (elite dragons fly nearby): the |cOXP_FRIENDLY_Obsidian Sentinel|r (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an |cOXP_FRIENDLY_Obsidian Shard|r, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back." },
        { "xp", level = 40, text = "Reach level 40" },
        { "goto", x = 49.1, y = 13.7, zone = "1418" },
        { "complete", obj = 1, quest = 1956, text = "Obsidian Power Source: 1 (|cOXP_LOOT_Obsidian Power Source|r: |cOXP_FRIENDLY_Obsidian Sentinel|r)" },
      },
      { only = "Mage", source = "polestar:forever/class/mage/celestial-orb",
        { "text", text = "Mana Surges" },
        { "text", text = "Back to |cOXP_FRIENDLY_Tabetha|r. Accepting Mana Surges opens a rift beside her cottage and starts a 10 minute timer: twelve Mana Surges (level 40, Shock and Lightning Bolt) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out." },
        { "goto", x = 46.06, y = 57.09, zone = "1445" },
        { "turnin", quest = 1956, text = "Turn in Power in Uldaman" },
        { "target", name = "Tabetha" },
