        { "accept", optional = true, quest = 2846, text = "Accept Tiara of the Deep" },
        { "target", name = "Tabetha" },
      },
      { only = "Mage", source = "polestar:forever/class/mage/celestial-orb", when = { { "onquest", quests = { 2846 } } },
        { "text", text = "Tiara of the Deep in Zul'Farrak" },
        { "text", text = "Zul'Farrak, the troll dungeon in north-western Tanaris, needs a group of five; the guide waits for level 44. |cOXP_FRIENDLY_Hydromancer Velratha|r is one of the bosses by the sacred pool, and the tiara always drops." },
        { "xp", level = 44, text = "Reach level 44" },
