        { "complete", obj = 1, quest = 2846, text = "Tiara of the Deep: 1 (Tiara of the Deep: |cOXP_FRIENDLY_Hydromancer Velratha|r, Zul'Farrak)" },
        { "goto", x = 46.06, y = 57.09, zone = "1445" },
