      { only = "Warlock", source = "polestar:forever/class/warlock/orb-of-orahil",
        { "text", text = "Choose an acolyte" },
        { "text", text = "Pick one acolyte: you can take only one of their quests. |cOXP_FRIENDLY_Acolyte Wytula|r's felhound path ends with the Orb or |cOXP_LOOT_Staff of Dar'Orahil|r, the shadow versions; |cOXP_FRIENDLY_Acolyte Magaz|r's infernal path with the Orb or |cOXP_LOOT_Staff of Noh'Orahil|r, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back." },
        { "goto", x = 62.64, y = 35.3, zone = "1413" },
        { "accept", quest = 4962, text = "Accept Shard of a Felhound (|cOXP_FRIENDLY_Acolyte Wytula|r: she gives you the |cOXP_LOOT_Felhas Ruby|r)" },
