        { "target", name = "Acolyte Magaz" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/orb-of-orahil",
        { "text", text = "Mannoroc Coven" },
        { "text", text = "Mannoroc Coven fills south-central Desolace, east of Shadowprey Village. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the |cOXP_LOOT_Infernal Orb|r every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with Drain Soul: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)." },
        { "goto", x = 66.49, y = 77.94, zone = "1443" },
        { "complete", obj = 1, quest = 1799, text = "Infernal Orb: 1 (|cOXP_LOOT_Infernal Orb|r, from the Burning Blade Summoners)" },
        { "mob", name = "Burning Blade Summoner" },
        { "goto", x = 52.91, y = 68.14, zone = "1443" },
        { "complete", obj = 1, quest = 4962, text = "Imprisoned Felhound Spirit: 1 (|cOXP_LOOT_Imprisoned Felhound Spirit|r, from a |cOXP_ENEMY_Mana Eater|r, |cOXP_ENEMY_Mage Hunter|r or |cOXP_ENEMY_Ley Hunter|r)" },
        { "mob", name = "Mana Eater" },
        { "goto", x = 54.31, y = 71.14, zone = "1443" },
